async function act(action,data){if(busy)return false;busy=true;const buttonStates=[...document.querySelectorAll('button')].map(b=>[b,b.disabled]);buttonStates.forEach(([b])=>b.disabled=true);try{view=await call('/api/action',{action,data});render();return true}catch(e){toast(e.message,true);return false}finally{busy=false;buttonStates.forEach(([b,disabled])=>{if(b.isConnected)b.disabled=disabled})}}
